import{_ as t,c as n,o,ah as a}from"./chunks/framework.BssxmkiH.js";const h=JSON.parse('{"title":"Setup","description":"","frontmatter":{},"headers":[],"relativePath":"setup.md","filePath":"setup.md"}'),r={name:"setup.md"};function s(i,e,p,u,d,c){return o(),n("div",null,e[0]||(e[0]=[a('<h1 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to “Setup”">​</a></h1><p>This section assumes you&#39;ve sucessfully downloaded and imported the FastSky2 package and you are working with the <strong>Universal Render Pipeline</strong> or <strong>Built-in Render Pipeline</strong>.</p><h2 id="setting-up-the-fastskyrendererfeature" tabindex="-1">Setting up the FastSkyRendererFeature <a class="header-anchor" href="#setting-up-the-fastskyrendererfeature" aria-label="Permalink to “Setting up the FastSkyRendererFeature”">​</a></h2><blockquote><p><strong>URP</strong> Navigate to your active Renderer, scroll down to the &#39;Renderer Features&#39; section and add the <code>FastSkyRendererFeature</code>.</p></blockquote><blockquote><p><strong>Built-in Render Pipeline</strong> Navigate to your active Camera, and add the <code>FastSkyRendererFeature</code> component.</p></blockquote><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p>Performing this set overrides your current skybox material. Undoing this action won&#39;t undo the change.</p></div><h2 id="setting-up-your-environment" tabindex="-1">Setting up your environment <a class="header-anchor" href="#setting-up-your-environment" aria-label="Permalink to “Setting up your environment”">​</a></h2><p>Open up the lighting window and set the sun source (optional but recommended).</p><h2 id="setting-up-your-camera" tabindex="-1">Setting up your camera <a class="header-anchor" href="#setting-up-your-camera" aria-label="Permalink to “Setting up your camera”">​</a></h2><p>Open up the properties of your main camera and set the;</p><blockquote><p><strong>URP</strong></p><p><strong>Background Type</strong> to <strong>Uninitialized</strong>. This prevents an unnecessary rendering pass.</p></blockquote><blockquote><p><strong>Built-in Render Pipeline</strong></p><p><strong>Background Type</strong> to <strong>Nothing</strong>. This prevents an unnecessary rendering pass.</p></blockquote><div class="info custom-block github-alert"><p class="custom-block-title">INFO</p><p>Skipping this step is not illegal, but would incure an extra render pass that would get overriden by sky rendering process anyways.</p></div><h2 id="setting-up-the-fast-sky-component" tabindex="-1">Setting up the Fast Sky component <a class="header-anchor" href="#setting-up-the-fast-sky-component" aria-label="Permalink to “Setting up the Fast Sky component”">​</a></h2><p>Create a new volume profile and add the fast sky component. You can choose to add it to an existing volume profile in your scene, or create different volume profiles with the fast sky component for different states. See <a href="./state-blending">state blending</a> for more info.</p><p>Optional, but recommended, add the <strong>FastSkySceneConfig</strong> component to any game object in your scene. This component holds extra info such as moon transform and cloud shadow area. It also allows you to use <strong>astronomical positioning</strong>.</p>',16)]))}const g=t(r,[["render",s]]);export{h as __pageData,g as default};
